package main

import (
	"context"
	"flag"
	"os"
	"os/signal"
	"time"

	"legagent/app/services"
	"legagent/internal/moj"
)

// runImportLaws 把全國法規資料庫的全部法規寫入 PostgreSQL，每部法規一張表。
//
//	go run . import-laws             # 使用快取內的官方資料（快取過期才下載）
//	go run . import-laws -refresh    # 先重新下載最新資料
//	go run . import-laws -current    # 只匯入現行法規，略過已廢止者
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 建表與大量寫入是明確的維運動作，與伺服器啟動分開
// @ai:input args 子命令參數
// @ai:output none
// @ai:sideeffect 可能下載官方資料、建立 laws schema 與資料表、失敗時 os.Exit
func runImportLaws(args []string) {
	fs := flag.NewFlagSet("import-laws", flag.ExitOnError)
	cfgPath := fs.String("config", defaultConfigPath, "config.yaml 路徑")
	xmls := fs.String("xml", "", "逗號分隔之本地 XML 路徑；留空則使用官方資料（含快取）")
	refresh := fs.Bool("refresh", false, "忽略快取，重新下載官方資料")
	current := fs.Bool("current", false, "只匯入現行法規，略過已廢止者")
	_ = fs.Parse(args)

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	cfg, log := mustLoad(*cfgPath)
	maxAge := time.Duration(cfg.Rules.CacheMaxAgeHours) * time.Hour
	if *refresh {
		maxAge = time.Nanosecond
	}
	paths, err := resolveXML(ctx, *xmls, maxAge, cfg, log)
	if err != nil {
		log.Error("resolve xml failed", "err", err)
		os.Exit(1)
	}

	var laws []moj.Law
	for _, path := range paths {
		parsed, err := moj.ParseFile(path, moj.Filter{ExcludeRepealed: *current})
		if err != nil {
			log.Error("parse law xml failed", "path", path, "err", err)
			os.Exit(1)
		}
		log.Info("parsed law xml", "path", path, "laws", len(parsed))
		laws = append(laws, parsed...)
	}

	db := mustOpenDB(cfg, log)
	defer db.Close()

	stats, err := services.NewLawsService(db, log).Import(ctx, laws)
	if err != nil {
		db.Close()
		os.Exit(1)
	}
	log.Info("import done", "laws", stats.Laws, "repealed", stats.Repealed, "articles", stats.Articles)
}
